INSERT INTO articulos (
  slug, titulo, extracto, contenido, imagen_destacada, estado, metadata, created_at, updated_at, categoria_id, autor_id
) VALUES (
  'el-enigma-de-los-globos-alfabeticos', 'El Enigma de los Globos Alfabéticos', 'Dinámica de agilidad rítmica y composición lingüística donde las patrullas mantienen globos en el aire mientras rescatan letras para armar valores scouts.', '<h2>📜 Descripción de El Enigma de los Globos Alfabéticos</h2>
<p><b>El Enigma de los Globos Alfabéticos</b> es una dinámica scout de motricidad fina, trabajo cooperativo y estimulación del vocabulario. En esta actividad, cada patrulla o seisena recibe una serie de globos inflados que contienen en su interior pequeñas tarjetas con letras escritas. Los participantes deben mantener los globos flotando en el aire mediante toques constantes sin que ninguno toque el suelo, mientras revientan de manera controlada los globos requeridos para recuperar las letras y formar una palabra o frase emblema relacionada con la Ley y la Promesa Scout.</p>
<p>Esta dinámica ejercita la autoformación, la rapidez de pensamiento y la coordinación en Manada, Compañía y Tropa.</p>

<h2>🎲 ¿Cómo se juega El Enigma de los Globos Alfabéticos?</h2>
<p>Para llevar a cabo la dinámica con entusiasmo y seguridad, los dirigentes deben seguir estos pasos:</p>
<ul>
  <li><b>Distribución de Globos:</b> Cada equipo recibe 6 globos inflados que contienen letras escondidas en su interior.</li>
  <li><b>Vuelo Continuo:</b> A la señal del guía, los equipos comienzan a dar toques de palma a los globos para mantenerlos en el aire en todo momento.</li>
  <li><b>Rescate de Letras:</b> A la orden del dirigente, un participante de la patrulla debe capturar un globo al vuelo y reventarlo con cuidado sobre una colchoneta o manta scout para extraer la tarjeta con la letra.</li>
  <li><b>Composición del Enigma:</b> Los scouts restantes continúan manteniendo el resto de los globos a salvo mientras los rescatadores combinan las letras obtenidas para formar la palabra scout misteriosa (ej. <i>''LEALTAD''</i>, <i>''SERVICIO''</i> o <i>''HERMANDAD''</i>).</li>
  <li><b>Resolución del Desafío:</b> La primera patrulla que grite la palabra correcta y presente la lección de la Promesa obtiene la victoria de la ronda.</li>
</ul>

<h2>🏆 Cómputo de Puntos y Condición de Victory de El Enigma de los Globos Alfabéticos</h2>
<p>La actividad reconoce la precisión de vocabulario y el control motriz en el Tally:</p>
<ul>
  <li><b>Resolución Más Rápida del Enigma:</b> Otorgar 5 puntos a la patrulla o seisena que descifre y arme la palabra scout en primer lugar.</li>
  <li><b>Control de Vuelo Sostenido:</b> Otorgar 3 puntos al equipo que no deje caer ningún globo durante el proceso de rescate.</li>
  <li><b>Espíritu de Aprendizaje:</b> Otorgar 3 puntos a la unidad que explique con mayor profundidad el significado del valor scout descubierto.</li>
</ul>', '/uploads/el-enigma-de-los-globos-alfabeticos.webp', 'publicado', '{"areas": ["creatividad", "espiritualidad", "sociabilidad"], "unidades": ["manada", "compañía", "tropa"], "duracion": "20 minutos", "cantidad": "04 participantes", "lugares": ["Interior", "Exterior"], "materiales": ["Globos", "Tarjetas con Letras"], "objetivos": ["Incrementar conocimientos mediante el aprendizaje sistemático", "Reconocer valores espirituales en la Creación y el grupo", "Estimular el vocabulario y la rapidez mental", "Favorecer la cooperación rítmica"], "justificacion_areas": "El Enigma de los Globos Alfabéticos potencia la creatividad al incentivar la autoformación, el descubrimiento de palabras clave y el pensamiento estructurado. Fortalece la espiritualidad al conectar el significado de los conceptos armados con la vivencia reflexiva de la Promesa Scout. Desarrolla la sociabilidad al exigir el cumplimiento ético de las reglas de juego y el apoyo mutuo.", "variaciones": "<b>Globos de Colores por Seisena:</b> Asignar un color de globo diferente por unidad para trabajar palabras cruzadas colectivas.<br><b>El Mensaje del Báculo:</b> Reventar los globos presionándolos contra el báculo scout en lugar de las manos.<br><b>Enigma de Citas de Baden-Powell:</b> Ocultar palabras completas en lugar de letras para reconstruir una frase célebre del fundador.", "recomendaciones": "Asegurar que los restos de goma de los globos reventados sean recogidos inmediatamente por los beneficiarios para mantener impecable la limpieza del pañol o campo. Utilizar materiales biodegradables. Regular la altura del espacio para evitar tropiezos.", "objetivos_educativos": [{"id": "0fdac5b5-f76d-4141-9dba-397ca49a5fcc", "area": "Creatividad", "unidad": "Manada", "texto": "Participo en actividades donde puedo conocer algo nuevo.", "como_se_cumple": "Descubriendo nuevas palabras y conceptos scouts al rescatar las letras de los globos."}, {"id": "a7539c03-7e17-4e1b-8e3b-081c8a8161cc", "area": "Creatividad", "unidad": "Manada", "texto": "Investigo y descubro cómo funcionan las cosas.", "como_se_cumple": "Investigando activamente la combinación alfabética necesaria para descifrar el enigma."}, {"id": "1b5e42cb-c832-4c3a-8ed5-a3050b6e2285", "area": "Creatividad", "unidad": "Compañía", "texto": "Me intereso por conocer más sobre lo que pasa a mi alrededor.", "como_se_cumple": "Ampliando mi vocabulario e interesándome por la investigación de conceptos institucionales."}, {"id": "aacee532-b682-4d8e-8c5d-d6e9396162a4", "area": "Creatividad", "unidad": "Compañía", "texto": "Me preocupo por saber cada vez más sobre los temas que me interesan.", "como_se_cumple": "Profundizando de forma sistemática en el significado de la Ley y la Promesa en patrulla."}, {"id": "a93b3a5c-a023-4e0c-815d-c77c6700dd89", "area": "Creatividad", "unidad": "Tropa", "texto": "Me intereso por conocer más sobre lo que pasa a mi alrededor.", "como_se_cumple": "Fomentando la autoformación constante y el hábito de consultar el diccionario scout."}, {"id": "071e6f2d-cb33-48c7-a385-4c63d873b254", "area": "Creatividad", "unidad": "Tropa", "texto": "Me preocupo por saber cada vez más sobre los temas que me interesan.", "como_se_cumple": "Organizando con rigurosidad sistemática la estructuración de frases en el Tally de patrulla."}, {"id": "8e6e41e8-5ac4-48a0-82bc-08fe0461a18e", "area": "Espiritualidad", "unidad": "Manada", "texto": "He aprendido a reconocer la naturaleza como obra de Dios.", "como_se_cumple": "Reconociendo en la naturaleza y en los compañeros un regalo para compartir en alegría."}, {"id": "4c30bc21-ce45-4e13-995d-d9e0cce0159d", "area": "Espiritualidad", "unidad": "Manada", "texto": "Me gusta cuando las personas hacen cosas buenas por los demás.", "como_se_cumple": "Valorando el apoyo de los lobatos al mantener flotando los globos de la seisena."}, {"id": "8d4dc6a3-8e3a-45c5-b440-6cf075c44e82", "area": "Espiritualidad", "unidad": "Compañía", "texto": "Escucho a las demás y aprendo de ellas.", "como_se_cumple": "Escuchando con atención las sugerencias de la patrulla para descifrar el mensaje espiritual."}, {"id": "a533450a-b017-427b-9e4e-9910f097a9b9", "area": "Espiritualidad", "unidad": "Compañía", "texto": "Procuro que en mi patrulla nos escuchemos y aprendamos unas de otras.", "como_se_cumple": "Reflexionando comunitariamente sobre la aplicación práctica del valor scout descubierto."}, {"id": "58925561-3ea5-4144-a704-52e21dd78a3f", "area": "Espiritualidad", "unidad": "Tropa", "texto": "Escucho a los demás y aprendo de ellos.", "como_se_cumple": "Valorando las aportaciones de cada hermano scout en la búsqueda personal y comunitaria de Dios."}, {"id": "1311db4d-dddf-4870-9cb3-7403223abb6d", "area": "Espiritualidad", "unidad": "Tropa", "texto": "Procuro que en mi patrulla nos escuchemos y aprendamos unos de otros.", "como_se_cumple": "Promoviendo un ambiente de oración y escucha fraterna al término de la dinámica."}, {"id": "b69188bf-2391-43c1-a885-abd1b13912be", "area": "Sociabilidad", "unidad": "Manada", "texto": "Acepto las reglas que se ponen en mi casa, en la escuela y en la Manada.", "como_se_cumple": "Cumpliendo fielmente la regla de no dejar caer los globos al suelo."}, {"id": "2394dd5b-87b9-4f3d-9cdd-a42649139782", "area": "Sociabilidad", "unidad": "Manada", "texto": "Comprendo y respeto las normas que se han puesto en mi casa y en la escuela, aunque no siempre esté de acuerdo con ellas", "como_se_cumple": "Respetando el turno de reventado de globos asignado por el dirigente."}, {"id": "007e85ea-2b06-48c2-8ac1-873d59643aae", "area": "Sociabilidad", "unidad": "Compañía", "texto": "Conozco y respeto las principales normas de convivencia.", "como_se_cumple": "Favoreciendo el juego limpio y la limpieza del espacio compartido."}, {"id": "de2f5693-de4b-48f1-b870-3c62be99aea8", "area": "Sociabilidad", "unidad": "Compañía", "texto": "Respeto las normas de convivencia de los distintos ambientes en que actúo, aunque no siempre esté de acuerdo con ellas.", "como_se_cumple": "Aceptando con madurez los resultados de la competencia alfabética."}, {"id": "857f21bc-db3c-4e5e-bcd5-d3d331276fad", "area": "Sociabilidad", "unidad": "Tropa", "texto": "Conozco y respeto las principales normas de convivencia.", "como_se_cumple": "Fomentando el respeto y la convivencia armónica entre patrullas."}, {"id": "bbc48d53-f4aa-4de7-84d4-95614df76034", "area": "Sociabilidad", "unidad": "Tropa", "texto": "Respeto las normas de convivencia de los distintos ambientes en que actúo, aunque no siempre esté de acuerdo con ellas.", "como_se_cumple": "Asumiendo las normas sociales y de grupo como base de la hermandad scout."}]}'::jsonb, NOW(), NOW(), NULL, NULL
);

